#!/usr/bin/env python3
"""Offline OpenAPI 3.1 structure/ref/coverage checks. Does not contact services."""
from pathlib import Path
import argparse, collections, copy, hashlib, json, re
import yaml
from jsonschema import Draft202012Validator
ROOT = Path(__file__).resolve().parents[1]
class Loader(yaml.SafeLoader):
    yaml_implicit_resolvers = {k: [(tag, pattern) for tag, pattern in v if tag != 'tag:yaml.org,2002:timestamp'] for k, v in yaml.SafeLoader.yaml_implicit_resolvers.items()}
# Fail on duplicate YAML keys instead of silently accepting an overwritten operation.
def mapping(loader, node, deep=False):
    result = {}
    for key_node, value_node in node.value:
        key = loader.construct_object(key_node, deep=deep)
        if key in result:
            raise AssertionError(f'Duplicate YAML key: {key}')
        result[key] = loader.construct_object(value_node, deep=deep)
    return result
Loader.add_constructor(yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG, mapping)

def walk(node):
    if isinstance(node, dict):
        yield node
        for value in node.values(): yield from walk(value)
    elif isinstance(node, list):
        for value in node: yield from walk(value)

def source_digest(service):
    paths = sorted((ROOT / f'arena-{service}/src/main').rglob('*'))
    return {str(p.relative_to(ROOT)): hashlib.sha256(p.read_bytes()).hexdigest() for p in paths if p.is_file() and p.suffix in ('.java', '.yaml') and p.name not in ('application-dev.yaml','application-mail-local.yaml')}

def main():
    parser=argparse.ArgumentParser(); parser.add_argument('--update', action='store_true', help='Update source-review manifest and coverage report after reviewing generated spec changes');args=parser.parse_args()
    official=json.loads((ROOT/'docs/api/openapi-3.1-schema.json').read_text())
    report=['# API documentation coverage', '', 'Generated by `python3 scripts/validate-openapi.py --update` from checked Springdoc exports.', '', '| Service/module | Operations | Discovery gaps |', '|---|---:|---:|']
    for service in ('core','login'):
        file=ROOT/f'docs/api/arenaops-{service}-openapi.yaml';spec=yaml.load(file.read_text(), Loader=Loader)
        Draft202012Validator(official).validate(spec)
        assert spec['openapi']=='3.1.0'
        for node in walk(spec):
            if '$ref' in node:
                ref=node['$ref'];assert ref.startswith('#/'), f'Unapproved external ref: {ref}'
                target=spec
                for part in ref[2:].split('/'):target=target[part.replace('~1','/').replace('~0','~')]
        for name,schema in spec['components']['schemas'].items():Draft202012Validator.check_schema(schema)
        methods={'get','post','put','patch','delete','head','options','trace'};counts=collections.Counter();seen=set();ops=set()
        for path,item in spec['paths'].items():
            for method,op in item.items():
                if method not in methods: continue
                ops.add(f'{method.upper()} {path}')
                for field in ('summary','description','tags','security','responses','operationId'):assert field in op, (service,path,method,field)
                assert op['operationId'] not in seen, f'Duplicate operation ID: {op["operationId"]}';seen.add(op['operationId'])
                counts[op['tags'][0]]+=1
                for name in re.findall(r'\{([^}]+)\}',path):assert any(p['name']==name and p['in']=='path' and p.get('required') for p in op.get('parameters',[])), (path,name)
                for req in op['security']:
                    for scheme in req:assert scheme in spec['components']['securitySchemes']
                for status,response in op['responses'].items():
                    assert status!='422' and (status!='429' or (method=='post' and path in {'/api/public/facility-check-ins/inspect','/api/public/facility-check-ins/submit','/api/public/club/reservations'})), (path,status,'not implemented')
                    if int(status)>=400:
                        media=response['content']['application/json'];assert '$ref' in media['schema'] or 'oneOf' in media['schema'] or 'anyOf' in media['schema']
                        for example in media.get('examples',{}).values():
                            value=example['value'];code=value['errorCode'];actual=spec['x-error-catalog'][code];assert int(status)==actual['status'];assert value['description']==actual['description']
        documented_handlers={op['x-handler'] for item in spec['paths'].values() for method,op in item.items() if method in methods}
        for controller in (ROOT/f'arena-{service}/src/main/java').rglob('*.java'):
            source=controller.read_text()
            if not re.search(r'@(?:[\w.]+\.)?(?:RestController|Controller)\b',source): continue
            if '@io.swagger.v3.oas.annotations.Hidden\n@RestController' in source: continue
            package=re.search(r'package ([\w.]+);',source).group(1)
            for match in re.finditer(r'@(?:[\w.]+\.)?(Get|Post|Put|Patch|Delete|Request)Mapping(?:\([^\n]*?\))?\s*(?:@ResponseStatus\([^\n]*?\)\s*)?public\s+[^\n;{{]+?\s+(\w+)\s*\(',source):
                if 'annotations.Hidden' in source[max(0,match.start()-100):match.start()]: continue
                assert package+'.'+controller.stem+'#'+match.group(2) in documented_handlers, f'Uncovered controller method: {controller}#{match.group(2)}'
        generated=ROOT/f'arena-{service}/target/openapi/inventory.txt'
        if generated.exists():assert ops==set(generated.read_text().splitlines()), f'{service}: mapped endpoint coverage differs from specification'
        manifest=ROOT/f'docs/api/{service}-source-review.json';current=source_digest(service)
        if args.update:manifest.write_text(json.dumps(current,indent=2,sort_keys=True)+'\n')
        else:
            assert manifest.exists(), 'Missing source-review manifest; review then regenerate'
            assert current==json.loads(manifest.read_text()), f'{service}: source changed; review documentation and run --update'
        for name,total in sorted(counts.items()):report.append(f'| {service}: {name} | {total} | 0 |')
        report.append(f'| **{service} total** | **{len(ops)}** | **0** |')
        print(f'{service}: {len(ops)} operations; refs, schemas, security, examples and source-review manifest verified')
    report+=['', 'Discovery counts include explicit root/trailing-slash aliases. Core and Login are independently described. A zero discovery gap is not a claim that all runtime exception paths have been exercised.', '', '## Intentional exclusions', '- Framework `/error` dispatch in both services: sanitized error bodies are documented as reusable components, not a business API.', '- Login `TokenController.proxyRequest`: catch-all routing is delegation, not a finite resource endpoint; all documented Core resource paths can be called through the BFF with a session and identical verbs/bodies. It strips inbound Authorization/Cookie headers, adds the session Bearer token, refreshes once on upstream 401, and sanitizes downstream errors. No imaginary Core presence/public/legacy routes are added.', '- Spring-generated HEAD/OPTIONS and Actuator endpoints are infrastructure, not ordinary customer operations. Core `/actuator/health/readiness` is public; Login readiness is public and proxies this check. Other Actuator endpoints follow the existing service security/exposure settings.', '', '## Semantic audit limits and discrepancies', '- Annotation metadata is reviewed against handlers, service validation, advice and security filters. Static/source/snapshot checks cannot prove that every rare runtime or dependency exception maps exactly as documented; no real Keycloak, PostgreSQL, SMTP, payment or live service calls were executed.', '- Core FacilityFailure is a map with fieldErrors/conflicts (including empty collections); ordinary Core ErrorResponse omits nulls. Login adds optional conflicts to its error record and sanitizes downstream unknown/malformed bodies to a status-based code. Core concurrency errors may include CONCURRENT_CHANGE; ordinary Login errors do not.', '- Global 404/405/406 responses are routing/negotiation outcomes rather than promises attached indiscriminately to every operation. HTTP 413 is documented for profile uploads. HTTP 422 is not implemented. Public facility check-in advertises HTTP 429 rate limiting.', '- POST /api/academy/staff/{id}/invite is an exposed legacy handler whose service always rejects with STAFF_LOGIN_ACCESS_UNAVAILABLE after scope/resource checks; it has no advertised successful delivery response.', '- Request optional reference-field nullability is annotated in existing DTOs, and facility PATCH null clearing is explicit. Response entity/reference-field nullability and state-dependent business fixtures still require field-level review; this is not claimed as exhaustive runtime schema verification.', '- Known generator warning: springdoc 2.8.13 can log a non-fatal cloneViaJson/additionalProperties warning for map-valued schemas during repeated OpenAPI 3.1 requests. JSON/YAML and UI assets return HTTP 200, exports validate and snapshot drift checks pass; the warning remains unresolved and requires compatibility follow-up before claiming warning-free live documentation.', '- Examples are synthetic and schema-derived except explicitly documented conflict/body examples. Replace IDs and temporary browser authorization codes with real authorized test fixtures; they are not executable onboarding credentials.', '', '## Operational boundaries', 'Documentation is disabled by default; only the explicit local api-docs profile enables unauthenticated documentation access. Do not enable that profile on public/SIT/production deployments. Existing endpoint authorization is independent and unchanged. No Keycloak clients, passwords, realm roles or required actions were modified.']
    if args.update:(ROOT/'docs/api/COVERAGE.md').write_text('\n'.join(report)+'\n')

if __name__=='__main__':main()
